// GET /api/text -> text/plain
msg.statusCode = 200;
msg.headers = { "Content-Type": "text/plain; charset=utf-8" };
msg.payload = "простой текст от Node-RED";
return msg;

// GET /api/info -> JSON
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
msg.payload = { app: "node-red-lab2", author: "kunda" };
return msg;

// GET /api/items/:id?format=json|text
const rawId = msg.req.params.id;
const id = Number(rawId);
const format = msg.req.query.format || "json";

// 1) id должен быть целым положительным числом
if (!Number.isInteger(id) || id <= 0) {
    msg.statusCode = 400;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = { error: "id должен быть положительным числом" };
    return msg;
}

// 2) формат ответа
if (format !== "json" && format !== "text") {
    msg.statusCode = 400;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = { error: "недопустимый format" };
    return msg;
}

// 3) поиск элемента
if (id > 100) {
    msg.statusCode = 404;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = { error: "item " + id + " не найден" };
    return msg;
}

// 4) успешный ответ
if (format === "text") {
    msg.statusCode = 200;
    msg.headers = { "Content-Type": "text/plain; charset=utf-8" };
    msg.payload = "item " + id;
} else {
    msg.statusCode = 200;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = { id: id, name: "item-" + id, found: true };
}
return msg;
